components.css:
.ds-page-header { margin-bottom: 30px; font-family: var(--font-sans, Geist, Arial, sans-serif); }
.ds-page-header__line { display: flex; align-items: baseline; justify-content: space-between; gap: 32px; flex-wrap: nowrap; }
.ds-page-header__title { margin: 0; min-width: 0; font-size: 36px; font-weight: 500; line-height: 1.1; letter-spacing: -0.9px; color: var(--ink); text-wrap: pretty; }
.ds-page-header__right { display: flex; align-items: baseline; justify-content: flex-end; gap: 20px; flex-shrink: 0; }
.ds-page-header__reading { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 16px; row-gap: 4px; font-size: 14px; color: var(--ink-3); }
.ds-fact { white-space: nowrap; }
.ds-measure { white-space: nowrap; }
.ds-measure__figure { margin-right: 4px; font-weight: 500; font-variant-numeric: tabular-nums; color: var(--ink-2); }
.ds-page-header__action { transform: translateY(3px); align-self: center; }

.ds-list { list-style: none; margin: 0; padding: 0; font-family: var(--font-sans, Geist, Arial, sans-serif); }
.ds-row { display: flex; align-items: center; gap: 12px; min-height: 48px; padding: 12px 0; border-bottom: 1px solid var(--line); }
.ds-row__dot { flex-shrink: 0; width: 9px; height: 9px; border-radius: 9999px; }
.ds-row__body { min-width: 0; flex: 1; }
.ds-row__title { font-size: 16px; font-weight: 400; line-height: 1.35; letter-spacing: -0.01em; color: var(--ink); }
.ds-row__title--done { color: var(--ink-4); text-decoration: line-through; }
.ds-row__meta { font-family: var(--font-mono, 'Geist Mono', ui-monospace, monospace); font-size: 12px; font-variant-numeric: tabular-nums; color: var(--ink-3); }

.ds-btn-primary { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 40px; padding: 0 20px; border: none; border-radius: 9999px; background: var(--ink); color: var(--bg); font-family: var(--font-sans, Geist, Arial, sans-serif); font-size: 14px; font-weight: 500; cursor: pointer; transition: opacity 150ms; }
.ds-btn-primary:hover { opacity: 0.9; }
.ds-btn-primary:active { opacity: 0.7; }
.ds-btn-primary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.ds-btn-outline { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 40px; padding: 0 20px; border: 1px solid var(--line-strong); border-radius: 9999px; background: transparent; color: var(--ink); font-family: var(--font-sans, Geist, Arial, sans-serif); font-size: 14px; font-weight: 500; cursor: pointer; transition: border-color 150ms; }
.ds-btn-outline:hover { border-color: var(--ink-4); }
.ds-btn-outline:active { opacity: 0.7; }
.ds-btn-outline:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.ds-btn-control-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 36px; padding: 0 12px; border: 1px solid var(--line-strong); border-radius: 12px; background: transparent; color: var(--ink-3); font-family: var(--font-mono, 'Geist Mono', ui-monospace, monospace); font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; cursor: pointer; transition: color 150ms, border-color 150ms; }
.ds-btn-control-secondary:hover { border-color: var(--accent); color: var(--ink); }
.ds-btn-control-secondary:active { opacity: 0.7; }
.ds-btn-control-secondary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.ds-field { display: block; font-family: var(--font-sans, Geist, Arial, sans-serif); }
.ds-field:focus-within .ds-field__label { color: var(--accent-ink); }
.ds-field__label { display: block; margin-bottom: 8px; font-size: 12px; color: var(--ink-4); }
.ds-field__control { width: 100%; height: 36px; padding: 0 0 6px; border: none; border-bottom: 1px solid var(--line); border-radius: 0; background: transparent; color: var(--ink); font-family: inherit; font-size: 14px; outline: none; caret-color: var(--accent); transition: border-color 160ms; }
.ds-field__control::placeholder { color: var(--ink-4); }
.ds-field__control:hover { border-bottom-color: var(--line-strong); }
.ds-field__control:focus-visible { outline: none; border-bottom-color: var(--accent); }

.ds-card { border: 1px solid var(--line-strong); border-radius: 22px; background: var(--surface); box-shadow: var(--elevation-card); padding: 20px; font-family: var(--font-sans, Geist, Arial, sans-serif); }
.ds-card__head { margin: 0 0 6px; font-size: 16px; font-weight: 500; letter-spacing: -0.02em; color: var(--ink); }
.ds-card__body { margin: 0; font-size: 16px; font-weight: 400; line-height: 1.35; letter-spacing: -0.01em; color: var(--ink); }

.ds-tabs { display: inline-flex; align-items: center; gap: 2px; padding: 5px; border-radius: 9999px; background: var(--surface-2); font-family: var(--font-sans, Geist, Arial, sans-serif); }
.ds-tab { display: block; padding: 7px 18px; border-radius: 9999px; font-size: 14px; color: var(--ink-3); text-decoration: none; cursor: pointer; transition: color 150ms; }
.ds-tab:hover { color: var(--ink-2); }
.ds-tab--active { background: var(--surface); color: var(--ink); font-weight: 500; box-shadow: var(--elevation-card); }
.ds-tab:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.ds-checks { display: flex; align-items: center; gap: 14px; }
.ds-check { display: block; width: 19px; height: 19px; border-radius: 7px; border: 1.5px solid var(--line-strong); background: transparent; cursor: pointer; }
.ds-check--high { border-color: var(--priority-high); box-shadow: 0 0 0 3.5px var(--priority-high-halo); }
.ds-check--med { border-color: var(--priority-med); }
.ds-check:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.ds-tape { font-family: var(--font-mono, 'Geist Mono', ui-monospace, monospace); }
.ds-tape__track { position: relative; height: 44px; border-radius: 12px; background: var(--surface-2); overflow: hidden; }
.ds-tape__block { position: absolute; top: 0; bottom: 0; border-radius: 4px; }
.ds-tape__tick { position: absolute; top: 6px; bottom: 6px; width: 7px; border: 1.5px solid; border-radius: 3px; background: var(--surface); }
.ds-tape__now { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--ink); }
.ds-tape__ruler { display: flex; justify-content: space-between; margin-top: 6px; font-size: 11px; letter-spacing: 0.08em; font-variant-numeric: tabular-nums; color: var(--ink-3); }
